(function(root){'use strict';
const course='https://www.pandaaiquant.com/learninghub/newcourse';
const catalog=[
{id:'skill-trend',title:'趋势信号分析 AI Skill',kind:'AI Skill 接入位',concept:'样本外验证',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'把均线、突破和动量信号整理成可检查的研究任务；比赛版展示匹配逻辑，正式资源需由 PandaAI 确认。'},
{id:'strategy-value',title:'价值策略库',kind:'策略库接入位',concept:'回撤',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'学习如何把低估值、基本面和分批买入组合成策略，重点排查价值陷阱。'},
{id:'strategy-defense',title:'低波动与仓位控制策略库',kind:'策略库接入位',concept:'资金占用',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'从低波动、最大仓位、现金预留和回撤边界开始搭建防守策略。'},
{id:'factor-research',title:'因子研究库',kind:'因子库接入位',concept:'未来数据泄漏',requires:[],status:'active',access:'local',fee:'示例',url:course,description:'按数据时间、因子定义、样本外验证和交易成本检查研究结果。'},
{id:'course-cost',title:'交易成本基础课',kind:'课程中心',concept:'交易成本',requires:[],status:'active',access:'local',fee:'公开入口',url:course,description:'区分毛收益、手续费和净收益，再开始第一个量化任务。'}];
const map={trend:'skill-trend',value:'strategy-value',defense:'strategy-defense',research:'factor-research'};
function knowledge(s){const a=s.knowledgeAttempts||[],answered=new Set(a.map(x=>x.id)).size,correct=new Set(a.filter(x=>x.correct).map(x=>x.id)).size,accuracy=answered?Math.round(correct/answered*100):0,level=answered<2?'知识水平待观察':correct>=4&&accuracy>=75?'研究型高手':correct>=2?'有经验投资者':'入门小白';return {level,answered,correct,accuracy,limitation:answered<2?'答题证据不足，暂不判断能力。':'只代表本游戏知识题，不代表真实投资能力。'};}
function validate(result,state){if(!['mock','ai'].includes(result.mode))throw Error('画像来源无效');const ids=new Set(state.evidence.map(e=>e.id));if(!Array.isArray(result.labels)||result.labels.length>12)throw Error('标签数量无效');for(const l of result.labels){if(!/^[a-z][a-z0-9_-]{0,39}$/.test(l.id)||!l.text||!l.context||!Array.isArray(l.evidence_ids)||!l.evidence_ids.length||l.evidence_ids.some(x=>!ids.has(x)))throw Error('画像缺少有效证据');}for(const r of result.recommendations)if(!catalog.some(c=>c.id===r.resource_id&&c.status==='active'))throw Error('推荐目录无效');return result;}
function analyze(s){const labels=[],groups={trend:[],value:[],defense:[],research:[]},meta={trend:['趋势型','趋势交易员·赤霄'],value:['价值型','价值买手·知夏'],defense:['防守型','现金守门员·凛川'],research:['研究型','研究分析师·星澜']};for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(groups[e.value])groups[e.value].push(e);for(const [id,ev] of Object.entries(groups))if(ev.length)labels.push({id:'type_'+id,text:meta[id][0]+'偏好 · '+meta[id][1],evidence_ids:ev.map(e=>e.id),context:'本局选择和建设共 '+ev.length+' 点；这是偏好，不是能力',status:s.analystCorrections?.['type_'+id]?.status||'candidate',edited:s.analystCorrections?.['type_'+id]?.text||null});const ranked=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length),top=ranked[0],k=knowledge(s),recommendations=[];if(top[1].length)recommendations.push({resource_id:map[top[0]],reason:`你在 ${top[1].length} 条行为证据中最常选择${meta[top[0]][0]}路径，下一步适合用这个资源完成一个小任务。`,next_task:top[0]==='trend'?'选一个板块，写出进场和退出条件':top[0]==='value'?'选一个估值因子，检查是否存在价值陷阱':top[0]==='defense'?'给策略设置最大仓位和回撤边界':'检查一个因子的发布时间和样本外表现'});recommendations.push({resource_id:k.level==='入门小白'||k.level==='知识水平待观察'?'course-cost':'factor-research',reason:k.level+'：'+(k.level.includes('待观察')?'先完成基础题，再决定进阶方向。':'按当前知识证据匹配下一步难度。'),next_task:k.level==='入门小白'||k.level==='知识水平待观察'?'完成交易成本小练习':'在因子库完成一项样本外验证'});return validate({mode:'mock',version:5,knowledge:k,labels,narrative:top[1].length?`你最常走${meta[top[0]][0]}路线；知识题结果是“${k.level}”。两项分开计算。`:'还没有足够的策略选择。',recommendations},s);}
root.ProfileAnalyst={catalog,knowledge,validate,analyze};if(typeof module!=='undefined')module.exports=root.ProfileAnalyst;
})(typeof window==='undefined'?globalThis:window);
